      '.dswk-taskSub{font-size:11px;color:var(--dsw-alias-label-tertiary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}',
      '.dswk-taskOps{display:flex;gap:4px;opacity:0;transition:opacity .15s ease;}',
